import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Contacts Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contacts Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/contacts-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contacts Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/contacts-overview"}]]},"headers":[],"relativePath":"user-guide/contacts-overview.md","filePath":"user-guide/contacts-overview.md","lastUpdated":1785713264000}'),n={name:"user-guide/contacts-overview.md"};function r(s,e,c,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="contacts-module" tabindex="-1">Contacts Module <a class="header-anchor" href="#contacts-module" aria-label="Permalink to &quot;Contacts Module&quot;">​</a></h1><p>Third product module on the frozen platform. Mirrors the <a href="/user-guide/leads-overview">Leads</a> / <a href="/user-guide/tasks-overview">Tasks</a> reference architecture — a workspace directory of people, with assignment, notes, and an activity timeline. Organizations are first-class in <a href="/user-guide/companies-overview">Companies</a>; contacts may link via <code>company_id</code>.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/contacts">contacts.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/contacts">contacts-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/contacts">contacts-production.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/leads-overview">leads.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-contacts">../api/tenant-v1-contacts.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Name, email, phone, company (legacy string), job title, source</li><li>Optional link to a <a href="/user-guide/companies-overview">Company</a> via <code>company_id</code> (form company picker when Companies is installed)</li><li>Assignment (<code>created_by</code> / <code>assigned_to</code>) with assignee scoping via <code>contacts.assign</code></li><li>Notes (comments) + activity timeline</li><li>Table view with search, company filter, and <strong>My Contacts</strong> toggle</li><li>KPIs via <code>GET /contacts/stats</code></li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:contacts</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong></li><li>Audit + activity logging</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>contacts.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code></p><p>Enable Contacts from Marketplace (free). Only Leads and Tasks install automatically on new workspaces.</p><h2 id="lead-conversion" tabindex="-1">Lead conversion <a class="header-anchor" href="#lead-conversion" aria-label="Permalink to &quot;Lead conversion&quot;">​</a></h2><p>When both <strong>Leads</strong> and <strong>Contacts</strong> are installed, converting a lead creates (or links) a real Contact and stores <code>contact_id</code> on the lead. The Lead detail drawer shows a <strong>View contact</strong> link after conversion. Without Contacts installed, conversion remains the earlier status-only placeholder.</p><h2 id="company-link" tabindex="-1">Company link <a class="header-anchor" href="#company-link" aria-label="Permalink to &quot;Company link&quot;">​</a></h2><p>When <strong>Companies</strong> is installed, Contact create/edit can pick a linked organization (<code>company_id</code>). The free-text <code>company</code> field remains as a <strong>legacy</strong> display/search string and is synced from the linked Company name when a link is set. List/detail UIs prefer <code>linked_company.name</code>, falling back to the legacy string.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Deals / opportunities linked to contacts</li><li>Contact import/export</li><li>Follow-ups (see <a href="/user-guide/leads-overview">Leads</a> for that pattern)</li><li>Legacy company-string → Company backfill job (see <a href="/user-guide/companies-overview">Companies</a>)</li></ul>',15)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
